 sealed class ValueSource:IModule {
  readonly Dictionary<string,PortValue> values;
  public ModuleDescriptor Descriptor{get;}
  public ValueSource(IReadOnlyDictionary<string,PortValue> values){this.values=values.ToDictionary(p=>p.Key,p=>p.Value);Descriptor=new("configured-values","1","Inputs",[],values.Select(p=>new PortDescriptor(p.Key,p.Value.Kind,false){Cardinality=p.Value.Cardinality}).ToArray(),[]);}
  public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext c,CancellationToken token)=>ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,values));
 }
 sealed class PointProducer:IModule {
  public ModuleDescriptor Descriptor{get;}=new("point-source","1","Source",[],new[]{"Object1","Object2","Target1","Target2"}.Select(p=>new PortDescriptor(p,DataKind.Point)).Concat(new[]{"ObjectArray1","ObjectArray2","TargetArray1","TargetArray2"}.Select(p=>new PortDescriptor(p,DataKind.Point){Cardinality=ValueCardinality.Array})).ToArray(),[]);
  public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext c,CancellationToken token)=>ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,new Dictionary<string,PortValue>{["Object1"]=PortValue.Point(new(0,0)),["Object2"]=PortValue.Point(new(10,0)),["Target1"]=PortValue.Point(new(10,-5)),["Target2"]=PortValue.Point(new(30,-5)),["ObjectArray1"]=PortValue.PointArray([new(0,0),new(10,0)]),["ObjectArray2"]=PortValue.PointArray([new(0,10),new(10,10)]),["TargetArray1"]=PortValue.PointArray([new(10,-5),new(30,-5)]),["TargetArray2"]=PortValue.PointArray([new(10,15),new(30,15)])}));
