 static void Capture(Window window,string file){window.UpdateLayout();var shot=new RenderTargetBitmap((int)window.Width,(int)window.Height,96,96,PixelFormats.Pbgra32);shot.Render(window);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(shot));using var stream=File.Create(file);png.Save(stream);}
 static void Pump(){for(int i=0;i<5;i++){var frame=new System.Windows.Threading.DispatcherFrame();System.Windows.Threading.Dispatcher.CurrentDispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.ApplicationIdle,new Action(()=>frame.Continue=false));System.Windows.Threading.Dispatcher.PushFrame(frame);}}
 static IEnumerable<DependencyObject> Walk(DependencyObject d){yield return d;for(int i=0;i<VisualTreeHelper.GetChildrenCount(d);i++)foreach(var x in Walk(VisualTreeHelper.GetChild(d,i)))yield return x;}
